<script setup>
import { ref, computed, watch } from 'vue';
const props=defineProps({rows:Array,columns:Array,actions:{default:()=>['查看详情']},selectable:Boolean,statusOptions:{default:()=>[]},placeholder:{default:'搜索名称、编号或关键词'}});
const emit=defineEmits(['action','selection']);
const query=ref(''),status=ref('全部状态'),page=ref(1),pageSize=5;
const filtered=computed(()=>props.rows.filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(query.value.toLowerCase()))&&(status.value==='全部状态'||r.status===status.value)));
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize));
watch([query,status,()=>props.rows.length],()=>page.value=1);
function tone(v){return /正常|已完成|已发布|已启用|已记录|已确认|可用|已提交|已绑定/.test(v)?'success':/拒绝|停用|失败|错误/.test(v)?'danger':/等待|待|处理中|评测|草稿|排队|待确认|待复核/.test(v)?'warning':'info'}
</script>
<template><div class="data-grid"><div class="table-toolbar"><el-input v-model="query" :placeholder="placeholder" clearable aria-label="搜索列表"><template #prefix><Icon name="search" :size="17" /></template></el-input><el-select v-if="statusOptions.length" v-model="status" aria-label="状态筛选"><el-option v-for="s in ['全部状态',...statusOptions]" :key="s" :label="s" :value="s" /></el-select><span class="result-count">共 {{filtered.length}} 条</span></div><el-table :data="visible" row-key="id" empty-text="没有匹配记录，请调整关键词或筛选条件" @selection-change="emit('selection',$event)"><el-table-column v-if="selectable" type="selection" width="48" /><el-table-column v-for="col in columns" :key="col.key" :prop="col.key" :label="col.label" :min-width="col.width||130"><template #default="{row}"><el-tag v-if="col.key==='status'" :type="tone(row[col.key])" effect="light" round><span class="status-dot" />{{row[col.key]}}</el-tag><div v-else-if="col.key==='name'" class="name-cell"><span class="row-avatar" :class="row.color||''">{{String(row.name).slice(0,1)}}</span><div><strong>{{row.name}}</strong><small v-if="row.id">{{row.id}}</small></div></div><span v-else :class="{mono:col.mono}">{{row[col.key]??'—'}}</span></template></el-table-column><el-table-column label="操作" :min-width="actions.length>1?190:116" fixed="right"><template #default="{row}"><el-button v-for="a in actions" :key="a" link type="primary" @click="emit('action',a,row)">{{a}}</el-button></template></el-table-column></el-table><div class="table-footer"><span>仅展示当前授权范围内的数据</span><el-pagination v-model:current-page="page" :page-size="pageSize" :total="filtered.length" layout="prev, pager, next" /></div></div></template>
